const a1 = $items('MEMORIA1')
  .flatMap(i => i.json?.mensagem1 ?? [])
  .filter(v => v !== null && v !== undefined && v !== '');

const a2 = $items('MEMORIA2')
  .flatMap(i => i.json?.mensagem2 ?? [])
  .filter(v => v !== null && v !== undefined && v !== '');

const LIMIT = 300;
const combinacaoTexto1 = a1.slice(-LIMIT).join(' ');
const combinacaoTexto2 = a2.slice(-LIMIT).join(' ');

return [{ json: { combinacaoTexto1, combinacaoTexto2 } }];

// 1) Tente pegar do INPUT do Code node
const inputItem = $input.first();
let aiOutputRaw = inputItem?.json?.output;

// 2) Se não veio no input, tente do node "AI Agentcopia"
if (aiOutputRaw == null) {
  try {
    const prev = $items('AI Agente', 0, 0); // [execução, outputIndex]
    aiOutputRaw = prev?.[0]?.json?.output ?? null;
  } catch (e) {
    // Ignora: significa que o node não executou neste ramo
  }
}

// 3) Validação/conversão
if (aiOutputRaw == null) {
  throw new Error("Não encontrei 'output' no input nem no node 'AI Agentcopia'. Garanta a conexão/ordem de execução.");
}

let aiOutputStr;
if (typeof aiOutputRaw === 'string') {
  aiOutputStr = aiOutputRaw;
} else {
  aiOutputStr = String(aiOutputRaw);
}

// 4) Split por parágrafos (1+ linhas em branco)
const splittedArray = aiOutputStr.split(/\r?\n\s*\r?\n+/);

// 5) Formato n8n
return splittedArray.map(text => ({ json: { text } }));

