(() => {
  const d = $('Webhook1').item.json.body.data || {};

  const jids = [
    d.key.remoteJidAlt || "",
    d.key.remoteJid || ""
  ];

  // função para validar JID
  const isValid = (jid) => {
    if (!jid) return false;
    const num = jid.split('@')[0];
    // número válido = só dígitos antes do @ e tamanho de CPF/telefone
    return /^\d+$/.test(num) && num.length >= 10 && num.length <= 13;
  };

  // escolhe o primeiro JID válido da lista
  let jid = jids.find(isValid) || jids[1] || jids[0] || "";

  // extrai sufixo
  const sufixo = jid.match(/@.+$/)?.[0] || "";

  // extrai números
  let numero = jid.replace(/@.+$/, "").replace(/\D/g, "");

  // adiciona o 9 se vier só com 8 dígitos
  if (numero.length === 10) {
    const ddd = numero.slice(0, 2);
    const restante = numero.slice(2);
    numero = `${ddd}9${restante}`;
  }

  return numero + sufixo;
})()
}}

